{
  "items": [
    {
      "name": "Polynomial.sum_modByMonic_coeff",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] {p q : Polynomial R},\n  q.Monic → ∀ {n : ℕ}, q.degree ≤ ↑n → ∑ i, (Polynomial.monomial ↑i) ((p %ₘ q).coeff ↑i) = p %ₘ q"
    },
    {
      "name": "Polynomial.self_mul_modByMonic",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Ring R] {p q : Polynomial R}, q.Monic → q * p %ₘ q = 0"
    },
    {
      "name": "Polynomial.exists_eq_polynomial",
      "module_name": "Mathlib.NumberTheory.ClassNumber.AdmissibleCardPowDegree",
      "kind": "theorem",
      "type": "∀ {Fq : Type u_1} [inst : Fintype Fq] [inst_1 : Semiring Fq] {d m : ℕ},\n  Fintype.card Fq ^ d ≤ m →\n    ∀ (b : Polynomial Fq),\n      b.natDegree ≤ d →\n        ∀ (A : Fin m.succ → Polynomial Fq),\n          (∀ (i : Fin m.succ), (A i).degree < b.degree) → ∃ i₀ i₁, i₀ ≠ i₁ ∧ A i₁ = A i₀"
    },
    {
      "name": "Polynomial.mul_self_modByMonic",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] {p q : Polynomial R}, q.Monic → p * q %ₘ q = 0"
    },
    {
      "name": "Polynomial.modByMonic",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Ring R] → Polynomial R → Polynomial R → Polynomial R"
    },
    {
      "name": "Polynomial.divModByMonicAux",
      "module_name": "Mathlib.Algebra.Polynomial.Div",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Ring R] → Polynomial R → {q : Polynomial R} → q.Monic → Polynomial R × Polynomial R"
    }
  ]
}
